import http from 'node:http';
import {randomUUID, randomBytes} from 'node:crypto';

const QUESTION_MS = 20000;
const INTRO_MS = 2600;
const ROOM_TTL = 12 * 60 * 60 * 1000;
const rooms = new Map();
const error = message => { throw new Error(message); };

function validateQuiz(quiz) {
  if (!Array.isArray(quiz) || quiz.length < 1 || quiz.length > 100) error('Use 1–100 questions.');
  for (const q of quiz) {
    if (!q || typeof q.question !== 'string' || !q.question.trim() || q.question.length > 500) error('Every question needs text (up to 500 characters).');
    if (!Array.isArray(q.options) || q.options.length !== 4 || q.options.some(x => typeof x !== 'string' || !x.trim() || x.length > 250)) error('Every question needs four answers (up to 250 characters each).');
    if (!Number.isInteger(q.correct) || q.correct < 0 || q.correct > 3) error('Choose the correct answer for every question.');
  }
}

function finishRound(room, now) {
  if (room.phase !== 'question') return;
  const correct = room.quiz[room.round].correct;
  room.players.forEach(p => {
    p.lastCorrect = p.choice === correct;
    p.lastGain = p.lastCorrect ? 1000 + Math.max(0, Math.min(500, Math.round(500 * (room.endAt - p.answeredAt) / QUESTION_MS))) : 0;
    if (p.lastCorrect) p.steps++;
    p.score += p.lastGain;
  });
  room.phase = 'reveal';
  room.revealAt = now;
  room.updated = now;
  room.revision++;
}

function advanceClock(room, now) {
  if (room.phase === 'question' && now >= room.endAt) finishRound(room, now);
}

function startRound(room, now) {
  room.round++;
  if (room.round >= room.quiz.length) {
    room.phase = 'awards';
    room.awardsAt = now;
  } else {
    room.phase = 'question';
    room.startAt = now + INTRO_MS;
    room.endAt = room.startAt + QUESTION_MS;
    room.players.forEach(p => { p.choice = null; p.answeredAt = null; p.lastCorrect = null; p.lastGain = 0; });
  }
  room.updated = now;
  room.revision++;
}

function publicState(room, key, now) {
  const isHost = key === room.host;
  const me = room.players.findIndex(p => p.key && p.key === key);
  const q = room.quiz[room.round];
  return {
    id: room.id, isHost, me, now, revision: room.revision, phase: room.phase,
    round: room.round, total: room.quiz.length, startAt: room.startAt, endAt: room.endAt,
    revealAt: room.revealAt, awardsAt: room.awardsAt,
    question: q ? {question:q.question, options:q.options, correct:room.phase === 'reveal' ? q.correct : null} : null,
    players: room.players.map((p,i) => ({name:p.name, joined:!!p.key, score:p.score, steps:p.steps, answered:p.choice !== null, choice:i === me || room.phase === 'reveal' ? p.choice : null, lastCorrect:p.lastCorrect, lastGain:p.lastGain}))
  };
}

export function handleAPI(path, method, key, body, now = Date.now()) {
  if (path === 'create' && method === 'POST') {
    for (const [id, r] of rooms) if (now - r.updated > ROOM_TTL) rooms.delete(id);
    if (rooms.size >= 500) error('Room limit reached. Please try later.');
    if (!Array.isArray(body.names) || body.names.length < 1 || body.names.length > 8 || body.names.some(n => typeof n !== 'string' || !n.trim() || n.length > 50)) error('Enter 1–8 racer names, up to 50 characters each.');
    validateQuiz(body.quiz);
    const id = randomBytes(6).toString('hex'), host = randomUUID();
    const room = {id,host,quiz:body.quiz,round:-1,phase:'lobby',revision:1,updated:now,startAt:0,endAt:0,revealAt:0,awardsAt:0,
      players:body.names.map(name=>({name:name.trim(),key:null,score:0,steps:0,choice:null,answeredAt:null,lastCorrect:null,lastGain:0}))};
    rooms.set(id,room);
    return {id, host};
  }
  const room = rooms.get(path);
  if (!room || now - room.updated > ROOM_TTL) error('Room expired or not found. Ask your teacher for a new link.');
  advanceClock(room, now);
  if (method === 'GET') return publicState(room, key, now);
  if (method !== 'POST') error('Unsupported method.');
  const isHost = key === room.host;
  if (body.action === 'join') {
    if (!/^[a-zA-Z0-9-]{20,60}$/.test(key) || isHost) error('Please reload and join again.');
    if (room.players.some(p=>p.key === key)) return publicState(room,key,now);
    if (room.phase !== 'lobby') error('The race has already started.');
    if (!Number.isInteger(body.lane)) error('Choose a racer.');
    const p = room.players[body.lane];
    if (!p || p.key) error('This racer has already joined. Choose another name.');
    p.key = key;
  } else if (body.action === 'release' && isHost) {
    if (room.phase !== 'lobby') error('Racers can only be released before the race.');
    if (!Number.isInteger(body.lane) || !room.players[body.lane]) error('Choose a racer.');
    room.players[body.lane].key = null;
  } else if (body.action === 'start' && isHost) {
    if (room.phase !== 'lobby') return publicState(room,key,now);
    if (!room.players.some(p=>p.key)) error('Wait for at least one racer to join.');
    startRound(room,now);
  } else if (body.action === 'close' && isHost) {
    if (body.round === room.round && room.phase === 'question') finishRound(room,now);
  } else if (body.action === 'next' && isHost) {
    if (body.round !== room.round || room.phase !== 'reveal') return publicState(room,key,now);
    startRound(room,now);
  } else if (body.action === 'answer') {
    const p = room.players.find(p=>p.key && p.key === key);
    if (!p || room.phase !== 'question' || body.round !== room.round || now < room.startAt || now >= room.endAt) error('The answer window is closed.');
    if (!Number.isInteger(body.choice) || body.choice < 0 || body.choice > 3) error('Choose A, B, C or D.');
    if (p.choice !== null) return publicState(room,key,now);
    p.choice = body.choice;
    p.answeredAt = now;
    if (room.players.filter(p=>p.key).every(p=>p.choice !== null)) finishRound(room,now);
  } else error('This action is unavailable.');
  room.updated = now;
  room.revision++;
  return publicState(room,key,now);
}

export function createServer(page) {
  return http.createServer(async (req,res) => {
    const url = new URL(req.url,'http://localhost');
    res.setHeader('Cache-Control','no-store');
    res.setHeader('X-Content-Type-Options','nosniff');
    if (url.pathname === '/health') {res.writeHead(200);res.end('ok');return;}
    if (!url.pathname.startsWith('/api/')) {
      res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});
      res.end(page);return;
    }
    try {
      const chunks=[];let size=0;
      for await (const chunk of req) {size+=chunk.length;if(size>400000) error('Question bank is too large.');chunks.push(chunk);}
      const body = chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : {};
      const data = handleAPI(url.pathname.slice(5),req.method,req.headers['x-racer']||'',body);
      res.writeHead(200,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify(data));
    } catch (e) {res.writeHead(400,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify({error:e.message}));}
  });
}

